const state={page:'dashboard',sidebar:false,login:true,searchOpen:false,modal:null,vendorStep:1,vendorDraft:{},pipelineOrder:'ORD-001',demo:true,orderId:null,orderTab:'Overview',inventorySection:'Warehouse'};
function clone(x){return JSON.parse(JSON.stringify(x));}
function loadData(){try{const raw=localStorage.getItem('aravliCraftsData'); if(raw){const d=JSON.parse(raw); Object.assign(state,d.meta||{}); return d.data||clone(DEMO)}}catch(e){} return clone(DEMO)}
let data=loadData();
function normalizeData(){ if(!('weavingProduction' in data)) data.weavingProduction=state.demo?clone(DEMO.weavingProduction):[]; if(!('designApplications' in data)) data.designApplications=state.demo?clone(DEMO.designApplications):[]; data.designs ||= []; data.weaving ||= []; data.orders ||= []; data.vendors ||= []; data.materials ||= []; data.purchases ||= []; data.payments ||= []; data.dyeing ||= []; data.transport ||= []; data.notifications ||= []; }
normalizeData();
function persist(){localStorage.setItem('aravliCraftsData',JSON.stringify({meta:{demo:state.demo},data}));}
function esc(v){return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function money(v){return '₹'+Number(v||0).toLocaleString('en-IN')}
function badge(s){const c=['Completed','Active','Active Sample','Paid','In Stock'].includes(s)?'success':['Delayed','Overdue','Blocked','Rejected'].includes(s)?'danger':['Pending','Pending Verification','Low Stock','Requires Changes'].includes(s)?'warning':['In Progress','In Transit'].includes(s)?'info':'gray';return `<span class="badge ${c}">${esc(s)}</span>`}
function kpi(label,value,sub,trend='↗ +8.4%',ico='◈',warn=false){return `<div class="card kpi"><div class="kpi-top"><span class="label">${label}</span><span class="kpi-icon">${ico}</span></div><div class="value">${value}</div><div class="trend ${warn?'warn':''}">${trend} <span style="color:#94a3b8;font-weight:500">${sub}</span></div></div>`}
function spark(){return `<div class="spark"><svg viewBox="0 0 180 25" preserveAspectRatio="none"><polyline points="5,20 30,16 55,18 80,7 110,12 140,3 170,8" fill="none" stroke="#9aa9bb" stroke-width="1.7"/></svg></div>`}
function chartCard(title,body,legend=''){return `<div class="card chart-card"><div class="card-head"><h3>${title}</h3><span>Current operations</span></div><div class="chart">${body}</div>${legend?`<div class="legend">${legend}</div>`:''}</div>`}
function pageHead(eyebrow,title,sub,actions=''){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${sub}</p></div><div class="actions">${actions}</div></div>`}
function lineChart(valsA=[42,51,48,63,58,72,68,84,92],valsB=[30,38,36,47,42,55,51,64,71]){const path=a=>a.map((v,i)=>`${i*(100/(a.length-1))},${100-v}`).join(' ');return `<svg viewBox="0 0 100 100" preserveAspectRatio="none"><g stroke="#e9eef5" stroke-width=".5">${[20,40,60,80].map(y=>`<line x1="0" y1="${y}" x2="100" y2="${y}"/>`).join('')}</g><polyline points="${path(valsA)}" fill="none" stroke="#2563eb" stroke-width="2"/><polyline points="${path(valsB)}" fill="none" stroke="#10b981" stroke-width="2"/></svg>`}
function barChart(vals=[72,58,48,39,31,24]){return `<svg viewBox="0 0 100 100" preserveAspectRatio="none"><g>${vals.map((v,i)=>`<rect x="${i*16+4}" y="${100-v}" width="10" height="${v}" rx="1" fill="#2563eb" opacity="${.55+i*.06}"/>`).join('')}</g></svg>`}
function tableCard(headers,rows,opts={}){return `<div class="card table-card"><div class="table-tools"><input placeholder="${esc(opts.placeholder||'Search records...')}" oninput="filterTable(this)">${opts.add?`<button class="btn sm primary" onclick="openModal('${opts.add}')">+ Add</button>`:''}<button class="btn sm" onclick="toast('Filter controls are available in the table search')">☷ Filter</button><button class="btn sm" onclick="toast('Sort controls opened')">⇅ Sort</button><span style="margin-left:auto;font-size:9px;color:#94a3b8">${rows.length} records</span></div><div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div></div>`}
function orderOptions(selected=''){return data.orders.map(o=>`<option value="${o.id}" ${selected===o.id?'selected':''}>${o.id} — ${esc(o.customer)}</option>`).join('')}
function customerOptions(){return data.orders.map(o=>`<option value="${esc(o.customer)}">${esc(o.customer)} · ${o.id}</option>`).join('')}
function ensureRealData(){if(state.demo){state.demo=false; data={orders:[],vendors:[],materials:[],purchases:[],payments:[],dyeing:[],designs:[],weaving:[],transport:[],notifications:[]};persist();toast('Demo data removed. You are now working with live workspace data.','success')}}

function attention(){return `<div class="card chart-card"><div class="card-head"><h3>Attention Required</h3><span>Priority items</span></div><div class="attention-grid">${data.notifications.slice(0,6).map(n=>`<div class="attention-item ${n.priority==='High'?'danger':''}"><span class="signal"></span><div><strong>${esc(n.type)}</strong><small>${esc(n.reference)} · ${esc(n.time)}</small></div></div>`).join('')||'<div class="empty">No attention items.</div>'}</div></div>`}
function inventoryDistribution(){const sections=[['Warehouse',60,'Warehouse'],['Vendor 1',18,'Vendor'],['Vendor 2',10,'Vendor'],['Dyeing',7,'Dyeing'],['Production',5,'Production']];return `<div class="card chart-card"><div class="card-head"><h3>Inventory Distribution</h3><span>Click a section for complete details</span></div><div style="padding:10px 0">${sections.map((x,i)=>`<button class="distribution-row" onclick="openInventorySection('${x[2]}','${x[0]}')"><span>${x[0]}</span><div class="progress" style="flex:1"><span style="width:${x[1]}%"></span></div><b>${x[1]}%</b></button>`).join('')}</div></div>`}
function pipeline(){const o=data.orders.find(x=>x.id===state.pipelineOrder)||data.orders[0];if(!o)return `<div class="card chart-card"><div class="empty">Create an order to see its pipeline.</div></div>`;const p=o.designs[0]?.progress||0;const stages=[['Order Created',100],['Design',100],['Material Purchase',Math.max(20,p-20)],['Warehouse',Math.max(10,p-10)],['Dyeing',Math.min(100,p)],['Weaving',Math.max(0,p-10)],['Transport',Math.max(0,p-18)],['Completed',o.status==='Completed'?100:Math.max(0,p-35)]];return `<div class="card chart-card"><div class="card-head"><h3>Order Pipeline</h3><select class="compact-select" onchange="state.pipelineOrder=this.value;render()">${orderOptions(state.pipelineOrder)}</select></div><div class="pipeline-caption"><strong>${esc(o.id)}</strong> · ${esc(o.customer)} · POC: ${esc(o.poc||'—')}</div><div class="funnel">${stages.map((x,i)=>`<div class="funnel-row"><div class="funnel-label">${x[0]}</div><div class="funnel-bar" style="width:${Math.max(18,x[1])}%">${x[1]}%</div></div>`).join('')}</div></div>`}
function vendorSpend(){const vendors=[...new Set(data.payments.map(p=>p.vendor))];return `<div class="card chart-card"><div class="card-head"><h3>Vendor Spend</h3><span>Click a vendor for order-wise payment details</span></div><div class="vendor-spend-list">${(vendors.length?vendors:['Kashi Yarn Traders','Dyeing Vendor A','Ganga Weaving Works','Shree Logistics']).map((v,i)=>{const total=data.payments.filter(p=>p.vendor===v).reduce((s,p)=>s+p.amount,0)||[420000,380000,290000,210000][i%4];return `<button class="vendor-spend" onclick="openVendorPayments('${esc(v)}')"><span class="vendor-rank">${i+1}</span><span class="vendor-name">${esc(v)}</span><span class="vendor-bar"><i style="width:${Math.min(100,total/4500)}%"></i></span><strong>${money(total)}</strong></button>`}).join('')}</div></div>`}
function dashboard(){
 const rows=data.orders.slice(0,8).map(o=>`<tr onclick="openOrder('${o.id}')"><td><strong class="link">${o.id}</strong></td><td>${esc(o.customer)}</td><td>${esc(o.poc||'—')}</td><td>${money(o.amount)}</td><td>${badge(o.status)}</td><td>${o.delivery}</td><td><button class="btn sm" onclick="event.stopPropagation();openOrder('${o.id}')">View</button></td></tr>`);
 return pageHead('OPERATIONS INTELLIGENCE','Good morning, ANKAN','Aravli Crafts operations overview for today.',`<button class="btn">▣ 28 Sep 2026</button><button class="btn primary" onclick="openModal('createOrder')">+ Create Order</button>`)+
 `<div class="grid kpi-grid">${kpi('Active Orders',data.orders.filter(o=>o.status!=='Completed').length,'Live order records','↗ +12.4%','▤')}${kpi('Inventory Value','₹24.8L','Current valuation','↗ +6.8%','▦')}${kpi('Pending Vendor Payments','₹8.42L','Order-linked payables','↗ +4.1%','₹',true)}${kpi('Warehouse Stock','18,420 kg','Available material','↗ +7.2%','▦')}${kpi('Materials With Vendors','7,860 kg','Across active vendors','↗ +2.4%','♙')}${kpi('Production In Progress','42 orders','Weaving operations','↗ +5.9%','⚙')}${kpi('Transport In Transit','23','5 due today','↗ +8.1%','➜')}</div>
 <div class="grid two-col" style="margin-top:16px">${inventoryDistribution()}${pipeline()}</div>
 <div class="grid two-col" style="margin-top:16px">${vendorSpend()}${attention()}</div>
 <div style="margin-top:16px">${pageHead('ORDER OPERATIONS','Recent Orders','One Order ID can contain multiple Design IDs. Dashboard summarizes at order level.',`<button class="btn" onclick="navigate('orders')">View all orders →</button>`)}${tableCard(['Order ID','Customer / Project','POC','Total Amount','Status','Expected Completion','Actions'],rows,{placeholder:'Search order ID, customer, POC...'})}</div>`;
}
function ordersPage(){
 const rows=data.orders.map(o=>`<tr><td><strong class="link" onclick="openOrder('${o.id}')">${o.id}</strong></td><td>${o.date}</td><td>${esc(o.customer)}</td><td>${esc(o.poc||'—')}</td><td>${o.designs.map(d=>`<span class="chip">${d.id}</span>`).join(' ')}</td><td>${o.designs.map(d=>`${d.qty} ${d.unit}`).join(' + ')}</td><td>${money(o.amount)}</td><td>${badge(o.status)}</td><td><button class="btn sm" onclick="openOrder('${o.id}')">View</button></td></tr>`);
 return pageHead('ORDER MANAGEMENT','Orders','One customer + one Order ID can carry multiple designs and production lines.',`<button class="btn">⇩ Export</button><button class="btn primary" onclick="openModal('createOrder')">+ Create Order</button>`)+`<div class="grid kpi-grid">${kpi('Total Orders',data.orders.length,'All order headers','↗ +11.2%','▤')}${kpi('Active Orders',data.orders.filter(o=>o.status!=='Completed').length,'Open orders','↗ +12.4%','◈')}${kpi('Completed',data.orders.filter(o=>o.status==='Completed').length,'Completed orders','↗ +8.6%','✓')}${kpi('Delayed',data.orders.filter(o=>o.status==='Delayed').length,'Requires attention','↘ -2.1%','!',true)}</div>${tableCard(['Order ID','Order Date','Customer','POC','Design IDs','Quantities','Total Cost','Status','Actions'],rows,{placeholder:'Search Order ID, customer, design, POC...'})}`;
}
function orderDetail(id){const o=data.orders.find(x=>x.id===id)||data.orders[0];if(!o)return pageHead('ORDER JOURNEY','No order selected','Create an order to begin.');const stages=['Order Created','Design Assigned','Material Purchased','Warehouse Received','Material Issued','Dyeing','Weaving','Transport','Payment','Finished Pieces'];const progress=o.designs.reduce((s,d)=>s+d.progress,0)/Math.max(1,o.designs.length);return `<div>${pageHead('ORDER JOURNEY',o.id,`${o.customer} · POC: ${o.poc||'—'}`,`<button class="btn" onclick="openModal('editOrder')">Edit</button><button class="btn primary" onclick="openModal('payment')">+ Payment</button>`)}<div class="card"><div class="order-hero"><div><div class="order-id">${o.id}</div><div class="order-name">${esc(o.customer)}</div><div style="color:#64748b;font-size:10px">${o.designs.length} design(s) · ${o.designs.map(d=>d.id).join(', ')} · POC ${esc(o.poc||'—')}</div></div><div>${badge(o.status)}</div></div><div class="summary-grid">${[['Order Date',o.date],['Expected Delivery',o.delivery],['POC',o.poc||'—'],['Designs',o.designs.length],['Total Cost',money(o.amount)],['Completion',Math.round(progress)+'%']].map(x=>`<div class="summary-box"><small>${x[0]}</small><strong>${x[1]}</strong></div>`).join('')}</div><div class="tabs">${['Overview','Design','Materials','Dyeing','Production','Transport','Finance','Documents','Activity'].map(t=>`<button class="${state.orderTab===t?'active':''}" onclick="state.orderTab='${t}';render()">${t}</button>`).join('')}</div><div style="padding:20px">${orderTabContent(o,stages,progress)}</div></div></div>`}
function orderTabContent(o,stages,progress){if(state.orderTab==='Design')return `<div class="grid two-col"><div>${tableCard(['Design ID','Design Name','Material','Qty','Stage','Progress'],o.designs.map(d=>`<tr><td>${d.id}</td><td>${esc(d.name)}</td><td>${esc(d.material)}</td><td>${d.qty} ${d.unit}</td><td>${esc(d.stage)}</td><td>${d.progress}%</td></tr>`))}</div><div class="card form-card"><div class="eyebrow">DESIGN-WISE MATERIAL CONSUMPTION</div><p class="muted">Detailed consumption is maintained from the Designs page.</p><button class="btn primary" onclick="navigate('designs');setTimeout(()=>openModal('consumption'),0)">Open Consumption</button></div></div>`;if(state.orderTab==='Finance')return `<div class="grid two-col"><div>${tableCard(['Payment ID','Order ID','Vendor','Invoice','Amount','Date','Method','Status'],data.payments.filter(p=>p.orderId===o.id).map(p=>`<tr><td>${p.id}</td><td>${p.orderId}</td><td>${esc(p.vendor)}</td><td>${p.invoice}</td><td>${money(p.amount)}</td><td>${p.date}</td><td>${p.method}</td><td>${badge(p.status)}</td></tr>`),{add:'payment'})}</div><div class="card form-card"><div class="eyebrow">PAYMENT CONTROL</div><h3>Order-linked payments</h3><p class="muted">Every payment is linked to an Order ID and vendor.</p><button class="btn primary" onclick="openModal('payment')">+ Add Payment</button></div></div>`;if(state.orderTab==='Materials')return `<div class="card form-card"><div class="eyebrow">MATERIALS</div><h3>Order material allocation</h3><div class="grid two-col">${o.designs.map(d=>`<div class="summary-box"><small>${d.id}</small><strong>${esc(d.material)}</strong><span class="muted">${d.qty} ${d.unit} · ${d.stage}</span></div>`).join('')}</div></div>`;return `<div class="grid two-col"><div><div class="eyebrow">COMPLETE ORDER TIMELINE</div><div class="timeline" style="margin-top:15px">${stages.map((s,i)=>`<div class="tl-item ${i<Math.ceil(progress/12)?'done':i===Math.ceil(progress/12)?'current':''}"><div class="tl-dot">${i<Math.ceil(progress/12)?'✓':i===Math.ceil(progress/12)?'•':'○'}</div><div class="tl-body"><strong>${s}</strong><small>${i<Math.ceil(progress/12)?'Completed':'Pending'} · ${o.id}</small></div></div>`).join('')}</div></div><div><div class="eyebrow">ORDER TRACEABILITY</div><div class="card" style="padding:15px;margin-top:12px;box-shadow:none;line-height:2"><b>Customer:</b> ${esc(o.customer)}<br><b>POC:</b> ${esc(o.poc||'—')}<br><b>Design IDs:</b> ${o.designs.map(d=>d.id).join(', ')}<br><b>Materials:</b> ${o.designs.map(d=>esc(d.material)).join(', ')}<br><b>Finance:</b> ${money(o.amount)} order value</div></div></div>`}

function vendorsPage(){
 const rows=data.vendors.map(v=>`<tr><td><strong class="link">${v.id}</strong></td><td>${esc(v.name)}</td><td>${esc(v.category)}</td><td>${esc(v.contact)}</td><td>${v.services.map(s=>`<span class="chip">${esc(s)}</span>`).join(' ')}</td><td>${badge(v.status)}</td><td><button class="btn sm" onclick="openVendorPayments('${esc(v.name)}')">Payments</button></td></tr>`);
 const serviceGroups={};data.vendors.forEach(v=>v.services.forEach(s=>(serviceGroups[s]??=[]).push(v)));
 return pageHead('VENDOR MANAGEMENT','Vendors','Supplier identity, service coverage and order-linked payment visibility.',`<button class="btn">⇩ Export</button><button class="btn primary" onclick="openModal('vendorWizard')">+ Onboard Vendor</button>`)+`<div class="card service-box"><div class="card-head"><h3>Vendor Service Coverage</h3><span>Vendor → service → Order IDs</span></div><div class="service-grid">${Object.entries(serviceGroups).map(([service,vs])=>`<div class="service-group"><div class="eyebrow">${esc(service)}</div>${vs.map(v=>`<button onclick="openVendorService('${esc(v.name)}','${esc(service)}')"><strong>${esc(v.name)}</strong><span>${data.orders.filter(o=>o.designs.some(d=>v.services.includes(service))).map(o=>o.id).join(', ')||'No linked orders yet'}</span></button>`).join('')}</div>`).join('')}</div></div><div style="margin-top:16px">${tableCard(['Vendor ID','Vendor Name','Category','Contact Person','Services','Status','Payment Details'],rows,{placeholder:'Search vendor, service, order...'})}</div>`;
}
function inventoryPage(){const rows=data.materials.map(m=>`<tr><td><strong class="link">${m.id}</strong></td><td>${esc(m.name)}</td><td>${esc(m.type)}</td><td>${m.purchased} kg</td><td>${m.warehouse} kg</td><td>${m.vendor} kg</td><td>${m.dyeing} kg</td><td>${m.production} kg</td><td>${m.available} kg</td><td>${badge(m.status)}</td><td><button class="btn sm" onclick="openMaterialDetail('${m.id}')">View</button></td></tr>`);return pageHead('MATERIAL CONTROL','Inventory & Warehouse','Track material across warehouse, vendors, dyeing and weaving.',`<button class="btn" onclick="openModal('material')">+ Add Material</button><button class="btn" onclick="openModal('receive')">+ Receive Material</button><button class="btn primary" onclick="openModal('issue')">+ Issue Material</button>`)+`<div class="grid kpi-grid">${kpi('Total Stock','18,420 kg','Across materials','↗ +7.2%','▦')}${kpi('Stock Value','₹24.8L','Current valuation','↗ +6.8%','₹')}${kpi('Low Stock Items',data.materials.filter(m=>m.status==='Low Stock').length,'Below threshold','↗ +2','!',true)}${kpi('Materials With Vendors','7,860 kg','Active vendor allocations','↗ +4.2%','♙')}${kpi('Materials In Dyeing','1,240 kg','Active sample jobs','↗ +5.6%','◈')}${kpi('Materials In Weaving','3,140 kg','Weaving operations','↗ +8.1%','⚙')}</div><div class="grid two-col" style="margin-top:16px">${inventoryDistribution()}<div class="card chart-card"><div class="card-head"><h3>Vendor Allocation</h3><span>Click vendor to inspect items</span></div><div class="vendor-allocation">${data.vendors.map(v=>`<button onclick="openInventorySection('Vendor','${esc(v.name)}')"><strong>${esc(v.name)}</strong><span>${data.materials.filter(m=>m.vendor>0).map(m=>m.name).slice(0,3).join(', ')}</span><b>View items →</b></button>`).join('')}</div></div></div><div style="margin-top:16px">${tableCard(['Material ID','Material Name','Type','Total Purchased','Warehouse Qty','Vendor Qty','Dyeing Qty','Weaving Qty','Available Qty','Status','Actions'],rows,{placeholder:'Search material...'})}</div>`}
function financePage(){const purchaseRows=data.purchases.map(p=>`<tr><td>${p.id}</td><td>${p.orderIds.map(id=>`<span class="chip">${id}</span>`).join(' ')}</td><td>${esc(p.vendor)}</td><td>${p.materials.map(m=>esc(m)).join(', ')}</td><td>${p.qty}</td><td>${p.rate}</td><td>${money(p.total)}</td><td>${p.date}</td><td>${p.invoice}</td><td>${badge(p.status)}</td></tr>`);const payRows=data.payments.map(p=>`<tr><td>${p.id}</td><td>${p.orderId}</td><td>${esc(p.vendor)}</td><td>${p.invoice}</td><td>${money(p.amount)}</td><td>${p.date}</td><td>${p.method}</td><td>${p.reference}</td><td>${badge(p.status)}</td><td><button class="btn sm" onclick="openModal('payment')">Edit</button></td></tr>`);return pageHead('FINANCE & PAYMENTS','Finance','Purchases and payments are managed together in one finance workspace.',`<button class="btn" onclick="openModal('purchase')">+ Purchase Entry</button><button class="btn primary" onclick="openModal('payment')">+ Payment Entry</button>`)+`<div class="grid kpi-grid">${kpi('Total Purchases','₹24.6L','This period','↗ +9.2%','₹')}${kpi('Vendor Payments','₹18.2L','Processed','↗ +6.4%','₹')}${kpi('Outstanding Payables','₹6.4L','Order-linked','↘ -3.2%','₹',true)}${kpi('Revenue','₹31.8L','Recognized','↗ +11.8%','₹')}${kpi('Gross Margin','₹7.2L','22.6% margin','↗ +2.4%','◒')}${kpi('Overdue Payments','₹1.2L','5 invoices','↘ -4.1%','!',true)}</div><div class="grid two-col" style="margin-top:16px">${chartCard('Revenue vs Expenses',lineChart([70,55,66,45,80,62,86,74,95],[42,50,48,61,49,58,60,68,57]),'<span><i></i> Revenue</span><span><i class="alt"></i> Expenses</span>')}${chartCard('Cost Breakdown',barChart([65,48,38,30,24,20]),'<span><i></i> Material</span><span><i class="orange"></i> Dyeing</span><span><i class="purple"></i> Weaving</span>')}</div><div class="finance-section"><div class="section-title"><h3>Purchases / Buying</h3><span>Grouped by vendor and Order IDs</span></div>${tableCard(['Purchase ID','Order ID(s)','Vendor','Materials','Quantity','Rate','Total Amount','Purchase Date','Invoice','Status'],purchaseRows,{placeholder:'Search order ID, vendor, material, invoice...',add:'purchase'})}</div><div class="finance-section"><div class="section-title"><h3>Vendor Payments</h3><span>Every payment is linked to an Order ID</span></div>${tableCard(['Transaction ID','Order ID','Vendor','Invoice Number','Amount','Payment Date','Method','Reference','Status','Actions'],payRows,{placeholder:'Search payment, order, vendor, invoice...',add:'payment'})}</div>`}

const genericConfig={
 dyeing:{ey:'DYEING MANAGEMENT',title:'Dyeing',sub:'Track material, shade, quantity and processing samples.',headers:['Dyeing ID','Order ID','Design ID','Material','Shade','Required Qty','Issued Qty','Vendor','Expected Completion','Status'],key:'dyeing'},
 designs:{ey:'DESIGN & COSTING',title:'Designs',sub:'Manage design IDs, costing and design-wise material consumption.',headers:['Design ID','Design Name','Size','Order ID','Materials','Yarn Types','Material Cost','Weaving Cost','Total Cost','Status','Actions'],key:'designs'},
 production:{ey:'WEAVING OPERATIONS',title:'Weaving',sub:'Monitor order-level weaving where one Order ID can contain multiple designs.',headers:['Order ID','Designs (Multiple)','Quantity','Produced','Remaining','Expected Completion','Status'],key:'weaving'},
 transport:{ey:'TRANSPORT MANAGEMENT',title:'Transport',sub:'Manage journeys, vehicles, e-way bills and material movement.',headers:['Transport ID','Order ID','E-way Bill No.','Vehicle','Vehicle Number','Driver','From','To','Quantity','Status'],key:'transport'},
 notifications:{ey:'NOTIFICATION CENTER',title:'Notifications',sub:'Operational alerts and priority-based attention.',headers:['Type','Reference','Message','Priority','Time','Status','Actions'],key:'notifications'},
 reports:{ey:'REPORTS & ANALYTICS',title:'Reports',sub:'Exportable business intelligence across operations, inventory and finance.',headers:['Metric','Current','Previous','Change','Period','Status'],key:'reports'}
};
function moduleGeneric(page){
 const c=genericConfig[page]||genericConfig.reports;
 let rows=[];
 if(page==='dyeing') rows=data.dyeing.map(r=>`<tr><td>${r.id}</td><td>${r.orderId}</td><td>${r.designId}</td><td>${r.material}</td><td>${r.shade}</td><td>${r.required} kg</td><td>${r.issued} kg</td><td>${r.vendor}</td><td>${r.expected}</td><td>${badge(r.status)}</td></tr>`);
 if(page==='designs') rows=data.designs.map(r=>`<tr><td>${r.id}</td><td>${esc(r.name)}</td><td>${r.size}</td><td>${r.orderId}</td><td>${esc(r.materials)}</td><td>${r.yarn}</td><td>${money(r.materialCost)}</td><td>${money(r.weavingCost)}</td><td>${money(r.totalCost)}</td><td>${badge(r.status)}</td><td><button class="btn sm" onclick="openModal('consumption')">Consumption</button></td></tr>`);
 if(page==='production') rows=data.weaving.map(r=>`<tr><td>${r.orderId}</td><td>${r.designs.map(d=>`<span class="chip">${esc(d)}</span>`).join(' ')}</td><td>${r.qty}</td><td>${r.produced}</td><td>${r.remaining}</td><td>${r.expected}</td><td>${badge(r.status)}</td></tr>`);
 if(page==='transport') rows=data.transport.map(r=>`<tr><td>${r.id}</td><td>${r.orderId}</td><td>${r.eway}</td><td>${r.vehicle}</td><td>${r.vehicleNo}</td><td>${r.driver}</td><td>${r.from}</td><td>${r.to}</td><td>${r.qty}</td><td>${badge(r.status)}</td></tr>`);
 if(page==='notifications') rows=data.notifications.map((r,i)=>`<tr><td>${r.type}</td><td>${r.reference}</td><td>${r.reference}</td><td>${badge(r.priority==='High'?'Overdue':'Pending')}</td><td>${r.time}</td><td>${r.status}</td><td><button class="btn sm" onclick="markNotification(${i})">Mark read</button></td></tr>`);
 if(page==='reports') rows=[['Order Completion Rate','86.2%','82.4%','↗ 3.8%','Sep 2026',badge('Healthy')],['Inventory Turnover','4.8x','4.2x','↗ 0.6x','Sep 2026',badge('Healthy')],['Material Utilization','91.4%','89.3%','↗ 2.1%','Sep 2026',badge('Healthy')]].map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`);
 let add=page==='dyeing'?'dyeing':page==='designs'?'design':page==='production'?'weaving':page==='transport'?'transport':page==='inventory'?'material':'generic';
 let base=pageHead(c.ey,c.title,c.sub,`<button class="btn">⇩ Export</button>${page!=='notifications'&&page!=='reports'?`<button class="btn primary" onclick="openModal('${add}')">+ Add Entry</button>`:''}`)+`<div class="grid kpi-grid">${kpi(page==='dyeing'?'Active Sample':page==='designs'?'Designs':page==='production'?'Weaving Orders':page==='transport'?'Shipments':'Records',page==='reports'?'—':rows.length,'Current module','↗ +8.2%','▤')}${page==='dyeing'?kpi('Design-linked','2','Active sample jobs','↗ +2','◇'):page==='designs'?kpi('Consumption Logs','12','Design-wise','↗ +4','▦'):page==='production'?kpi('Orders with Multiple Designs','1','Grouped by order','↗ +1','▤'):kpi('Attention','6','Current period','↗ +2','!',true)}</div>`;
 if(page==='designs') base+=`<div class="card chart-card design-consumption-banner"><div><div class="eyebrow">MATERIAL CONSUMPTION</div><h3>Design-wise consumption is managed here.</h3><p class="muted">Open any Design ID to record material issued, consumed, balance and wastage.</p></div><button class="btn primary" onclick="openModal('consumption')">+ Add Consumption</button></div>`;
 if(page==='designs') base+=`<div style="margin-top:16px">${tableCard(['Design ID','Design Name','Size','Order ID','Materials','Yarn Types','Material Cost','Weaving Cost','Total Cost','Status','Actions'],rows,{placeholder:'Search design, order, material...'})}</div>`;
 else base+=tableCard(c.headers,rows,{placeholder:`Search ${c.title.toLowerCase()}...`,add:page==='dyeing'?'dyeing':page==='transport'?'transport':null});
 if(page==='designs') base+=designApplicationTable();
 if(page==='production') base+=weavingProductionTable();
 return base;
}
function designApplicationTable(){const rows=data.designApplications.map((r,i)=>`<tr><td><strong class="link">${esc(r.designId)}</strong></td><td>${esc(r.name)}</td><td>${esc(r.size)}</td><td>${esc(r.material)}</td><td>${money(r.sampleCost)}</td><td><button class="btn sm primary" onclick="openDesignExtra(${i})">Extra Details</button></td></tr>`);return `<div style="margin-top:20px"><div class="section-title"><div><h3>Design Application / Sampling Register</h3><span>Design-wise sample application details from the Rishabh table.</span></div><button class="btn primary" onclick="openModal('designApplication')">+ Add Design Application</button></div>${tableCard(['Dsg ID','Name','Size','Material','Sample Cost','Extra Details'],rows,{placeholder:'Search design application...'})}</div>`}
function weavingProductionTable(){const rows=data.weavingProduction.map(r=>`<tr><td>${esc(r.orderId)}</td><td>${esc(r.loomMemo)}</td><td><span class="chip">${esc(r.designId)}</span></td><td>${r.qty}</td><td>${r.produced}</td><td>${r.remaining}</td><td>${r.startDate||'—'}</td><td>${r.endDate||'—'}</td><td>${r.progress}%</td><td>${esc(r.vendorId||'—')}</td><td>${badge(r.status)}</td></tr>`);return `<div style="margin-top:20px"><div class="section-title"><div><h3>Production / Weaving Register</h3><span>One Order ID can repeat across multiple Design IDs, with one production row per design.</span></div><button class="btn primary" onclick="openModal('weavingProduction')">+ Add Production Entry</button></div>${tableCard(['Order ID','Loom Memo','Dsg ID','Qty','Produced','Remaining','Start Date','End Date','%','Vendor ID','Status'],rows,{placeholder:'Search order, loom memo, design, vendor...'})}</div>`}

function modal(type){if(type==='vendorWizard')return vendorWizard();const configs={
 createOrder:['Create Order — One Order ID / Multiple Designs',createOrderForm()],
 editOrder:['Edit Order',editOrderForm()],
 payment:['Payment Entry',paymentForm()],
 purchase:['Purchase Entry',purchaseForm()],
 consumption:['Design-wise Material Consumption',consumptionForm()],
 vendorDetail:['Vendor Detail',vendorDetailForm()],
 vendorService:['Vendor Service & Order Details',vendorServiceForm()],
 materialDetail:['Material Detail',materialDetailForm()],
 receive:['Receive Material',receiveForm()],
 issue:['Issue Material',issueForm()],
 material:['Add Material',materialEntryForm()],
 dyeing:['Add Dyeing Sample',dyeingForm()],
 design:['Add Design',designForm()],
 transport:['Add Transport',transportForm()],
 weaving:['Add Weaving Entry',weavingForm()],
 weavingProduction:['Add Production / Weaving Entry',weavingProductionForm()],
 designApplication:['Add Design Application / Sampling Entry',designApplicationForm()],
 generic:['Add Record',genericForm()]
};const c=configs[type]||configs.generic;return `<div class="modal-backdrop"><div class="modal wide"><div class="modal-head"><h3>${c[0]}</h3><button class="close" onclick="closeModal()">×</button></div><div class="modal-body">${c[1]}</div><div class="modal-foot"><button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveModal('${type}')">Save</button></div></div></div>`}
function field(label,html,full=false){return `<div class="field ${full?'full':''}"><label>${label}</label>${html}</div>`}
function createOrderForm(){return `<div class="notice info">One customer/order header can contain multiple Design IDs. Enter the Order ID and Customer once, then add as many designs as required.</div><div class="form-grid">${field('Order ID *','<input id="order-id" placeholder="ORD-006">')}${field('Customer / Project Name *',`<input id="order-customer" list="customer-list" placeholder="Customer name"><datalist id="customer-list">${customerOptions()}</datalist>`)}${field('Order Date *','<input id="order-date" type="date" value="2026-09-28">')}${field('Expected Delivery *','<input id="order-delivery" type="date" value="2026-10-10">')}${field('POC (Project Operation Controller) *','<input id="order-poc" placeholder="POC name">')}${field('Priority','<select id="order-priority"><option>Normal</option><option>High</option><option>Critical</option></select>')}${field('Status','<select id="order-status"><option>Pending</option><option>In Progress</option><option>Delayed</option><option>Completed</option></select>')}${field('Total Order Amount *','<input id="order-amount" type="number" placeholder="245000">')}${field('Order Notes','<textarea id="order-notes" placeholder="Commercial / operational notes"></textarea>',true)}</div><div class="section-title"><h3>Design Lines</h3><button class="btn sm" onclick="addDesignLine()">+ Add Design ID</button></div><div id="design-lines">${designLine(1)}</div><div class="modal-inline-note">For the next design line, Order ID and Customer are automatically retained. Design ID is selected/entered separately.</div>`}
function designLine(n){return `<div class="design-line" id="design-line-${n}"><div class="design-line-head"><strong>Design ${n}</strong>${n>1?`<button class="btn sm" onclick="document.getElementById('design-line-${n}').remove()">Remove</button>`:''}</div><div class="form-grid compact-grid">${n>1?field('Order ID / Customer *',`<select class="existing-order"><option value="current">Use Order above</option>${orderOptions()}</select>`):''}${field('Design ID *',`<input class="design-id" list="design-options" placeholder="PAT-007">`)}${field('Design Name *','<input class="design-name" placeholder="Design name">')}${field('Material *','<input class="design-material" placeholder="60-count Yarn">')}${field('Quantity *','<input class="design-qty" type="number" placeholder="100">')}${field('Unit','<select class="design-unit"><option>kg</option><option>pieces</option><option>meters</option></select>')}${field('Current Stage','<select class="design-stage"><option>Design</option><option>Material Purchase</option><option>Warehouse</option><option>Dyeing</option><option>Weaving</option><option>Transport</option><option>Completed</option></select>')}${field('Design Amount','<input class="design-amount" type="number" placeholder="100000">')}${field('Design Status','<select class="design-status"><option>In Progress</option><option>Pending</option><option>Completed</option></select>')}</div></div>`}
function addDesignLine(){const box=document.getElementById('design-lines');const n=box.querySelectorAll('.design-line').length+1;box.insertAdjacentHTML('beforeend',designLine(n));const currentId=val('order-id')||'New Order';const currentCustomer=val('order-customer')||'Customer';const select=box.lastElementChild.querySelector('.existing-order');if(select)select.options[0].textContent=`${currentId} — ${currentCustomer} (Use Order Above)`;}
function editOrderForm(){const o=data.orders.find(x=>x.id===state.orderId)||data.orders[0];return `<div class="form-grid">${field('Order ID',`<input value="${o.id}" disabled>`)}${field('Customer',`<input id="edit-customer" value="${esc(o.customer)}">`)}${field('POC',`<input id="edit-poc" value="${esc(o.poc||'')}">`)}${field('Expected Delivery',`<input id="edit-delivery" type="date" value="${o.delivery}">`)}${field('Priority',`<select id="edit-priority"><option ${o.priority==='Normal'?'selected':''}>Normal</option><option ${o.priority==='High'?'selected':''}>High</option><option ${o.priority==='Critical'?'selected':''}>Critical</option></select>`)}${field('Status',`<select id="edit-status"><option ${o.status==='Pending'?'selected':''}>Pending</option><option ${o.status==='In Progress'?'selected':''}>In Progress</option><option ${o.status==='Delayed'?'selected':''}>Delayed</option><option ${o.status==='Completed'?'selected':''}>Completed</option></select>`)}</div>`}
