function designExtraModal(){const r=data.designApplications[state.modalData?.index]||{};const items=[['Design ID',r.designId],['Name',r.name],['Size',r.size],['Material',r.material],['Sample Cost',money(r.sampleCost)],['Full Material Details',r.materialDetails],['Dyeing Colour Details',r.dyeingDetails],['Weight — Gross',r.weightGross],['Weight — Net',r.weightNet],['Sample Maker Vendor ID',r.sampleVendorId],['No. of Colours Available',r.colourCount],['EPI',r.epi],['PPI',r.ppi],['Size Breakdown',r.sizeBreakdown],['Finishing Type',r.finishingType],['Washing',r.washing],['Washing Type & Details',r.washingDetails],['Loom Type',r.loomType],['Date of Sampling',r.samplingDate],['No. of Sampling',r.noOfSampling]];return `<div class="modal-backdrop"><div class="modal wide"><div class="modal-head"><h3>${esc(r.designId||'Design')} · Extra Details</h3><button class="close" onclick="closeModal()">×</button></div><div class="modal-body"><div class="summary-grid" style="padding:0">${items.map(x=>`<div class="summary-box"><small>${esc(x[0])}</small><strong>${esc(x[1]??'—')}</strong></div>`).join('')}</div></div><div class="modal-foot"><button class="btn" onclick="closeModal()">Close</button></div></div></div>`}
function openDesignExtra(index){state.modalData={index};openModal('designExtra')}
function saveWeavingProduction(){const r={id:'WVG-'+String(data.weavingProduction.length+1).padStart(3,'0'),orderId:val('wvp-order'),loomMemo:val('wvp-loom'),designId:val('wvp-design'),qty:Number(val('wvp-qty')||0),produced:Number(val('wvp-produced')||0),remaining:Number(val('wvp-remaining')||0),startDate:val('wvp-start'),endDate:val('wvp-end'),progress:Number(val('wvp-progress')||0),vendorId:val('wvp-vendor'),status:val('wvp-status')};if(!r.orderId||!r.loomMemo||!r.designId||!r.qty){toast('Order ID, Loom Memo, Design ID and Quantity are required','error');return}data.weavingProduction.push(r);persist();closeModal();render();toast('Production / Weaving entry saved','success')}
function saveDesignApplication(){const r={id:'DSG-APP-'+String(data.designApplications.length+1).padStart(3,'0'),designId:val('da-design'),name:val('da-name'),size:val('da-size'),material:val('da-material'),sampleCost:Number(val('da-sample-cost')||0),materialDetails:val('da-material-details'),dyeingDetails:val('da-dyeing-details'),weightGross:val('da-weight-gross'),weightNet:val('da-weight-net'),sampleVendorId:val('da-sample-vendor'),colourCount:Number(val('da-colours')||0),epi:Number(val('da-epi')||0),ppi:Number(val('da-ppi')||0),sizeBreakdown:val('da-size-breakdown'),finishingType:val('da-finishing'),washing:val('da-washing'),washingDetails:val('da-washing-details'),loomType:val('da-loom-type'),samplingDate:val('da-sampling-date'),noOfSampling:Number(val('da-no-sampling')||0)};if(!r.designId||!r.name||!r.size||!r.material||!r.sampleCost){toast('Design ID, Name, Size, Material and Sample Cost are required','error');return}data.designApplications.push(r);persist();closeModal();render();toast('Design application saved','success')}

function vendorWizard(){const d=state.vendorDraft||{};const input=(id,key,attrs='')=>`<input id="${id}" value="${esc(d[key]||'')}" ${attrs}>`;return `<div class="modal-backdrop"><div class="modal wide"><div class="modal-head"><h3>Vendor Onboarding · Step ${state.vendorStep} of 5</h3><button class="close" onclick="closeModal()">×</button></div><div class="modal-body"><div class="stepper">${['Identification','Compliance','Banking','Services','Review'].map((x,i)=>`<div class="step ${i+1===state.vendorStep?'active':i+1<state.vendorStep?'done':''}">${i+1}. ${x}</div>`).join('')}</div>${state.vendorStep===1?`<div class="form-grid">${field('Vendor ID *',input('vw-id','id','placeholder="VND-0005"'))}${field('Vendor Name *',input('vw-name','name','placeholder="Vendor name"'))}${field('Category *',input('vw-category','category','placeholder="Raw Materials"'))}${field('Contact Person *',input('vw-contact','contact'))}${field('Phone',input('vw-phone','phone'))}${field('Email',input('vw-email','email','type="email"'))}${field('Address',`<textarea id="vw-address">${esc(d.address||'')}</textarea>`,true)}</div>`:state.vendorStep===2?`<div class="form-grid">${field('PAN',input('vw-pan','pan'))}${field('GSTIN',input('vw-gst','gst'))}${field('Compliance Status','<select id="vw-compliance"><option>Pending Verification</option><option>Verified</option></select>')}${field('GST Certificate','<input id="vw-gst-cert" type="file">')}${field('PAN Card','<input id="vw-pan-card" type="file">')}</div>`:state.vendorStep===3?`<div class="form-grid">${field('Bank Name',input('vw-bank','bank'))}${field('Account Number',input('vw-account','account'))}${field('IFSC',input('vw-ifsc','ifsc'))}${field('Account Holder Name',input('vw-holder','holder'))}</div>`:state.vendorStep===4?`<div class="form-grid">${field('Services *',`<select id="vw-services" multiple style="min-height:160px">${['Dyeing','Finishing','Transportation','Yarn Supply','Weaving','Raw Materials'].map(x=>`<option ${d.services?.includes(x)?'selected':''}>${x}</option>`).join('')}</select>`)}${field('Vendor Status','<select id="vw-status"><option>Active</option><option>Pending Verification</option><option>Blocked</option></select>')}</div>`:`<div class="summary-grid" style="padding:0">${[['Vendor ID',d.id],['Vendor Name',d.name],['Category',d.category],['Contact Person',d.contact],['Services',(d.services||[]).join(', ')],['Status',d.status||'Pending Verification']].map(x=>`<div class="summary-box"><small>${x[0]}</small><strong>${esc(x[1]||'—')}</strong></div>`).join('')}</div>`}</div><div class="modal-foot">${state.vendorStep>1?`<button class="btn" onclick="captureVendorStep();state.vendorStep--;openModal('vendorWizard')">Back</button>`:''}${state.vendorStep<5?`<button class="btn primary" onclick="captureVendorStep();state.vendorStep++;openModal('vendorWizard')">Continue</button>`:`<button class="btn primary" onclick="captureVendorStep();saveVendorWizard()">Submit Vendor</button>`}</div></div></div>`}
function captureVendorStep(){const d=state.vendorDraft||{};if(state.vendorStep===1){Object.assign(d,{id:val('vw-id'),name:val('vw-name'),category:val('vw-category'),contact:val('vw-contact'),phone:val('vw-phone'),email:val('vw-email'),address:val('vw-address')});}else if(state.vendorStep===2){Object.assign(d,{pan:val('vw-pan'),gst:val('vw-gst'),compliance:val('vw-compliance')});}else if(state.vendorStep===3){Object.assign(d,{bank:val('vw-bank'),account:val('vw-account'),ifsc:val('vw-ifsc'),holder:val('vw-holder')});}else if(state.vendorStep===4){d.services=[...document.querySelectorAll('#vw-services option:checked')].map(o=>o.value);d.status=val('vw-status');}state.vendorDraft=d;}

function openInventorySection(type,label){state.inventorySection=label;openModal('inventorySection')}
function openVendorPayments(vendor){state.modalData={vendor};openModal('vendorPayments')}
function openVendorService(vendor,service){state.modalData={vendor,service};openModal('vendorService')}
function openMaterialDetail(id){state.modalData={id};openModal('materialDetail')}
function markNotification(i){if(data.notifications[i])data.notifications[i].status='Read';persist();render();toast('Notification marked read','success')}
function saveModal(type){ensureRealData();if(type==='createOrder')return saveOrder();if(type==='editOrder')return saveEditOrder();if(type==='payment')return savePayment();if(type==='purchase')return savePurchase();if(type==='consumption')return saveConsumption();if(type==='receive')return saveReceive();if(type==='issue')return saveIssue();if(type==='material')return saveMaterial();if(type==='dyeing')return saveDyeing();if(type==='design')return saveDesign();if(type==='transport')return saveTransport();if(type==='weaving')return saveWeaving();if(type==='weavingProduction')return saveWeavingProduction();if(type==='designApplication')return saveDesignApplication();if(type==='vendorWizard')return saveVendorWizard();closeModal();persist();render();toast('Record saved successfully','success')}
function val(id){return document.getElementById(id)?.value?.trim()||''}
function saveOrder(){const id=val('order-id'),customer=val('order-customer');if(!id||!customer){toast('Order ID and Customer are required','error');return}const lines=[...document.querySelectorAll('.design-line')].map(x=>({id:x.querySelector('.design-id').value.trim(),name:x.querySelector('.design-name').value.trim(),material:x.querySelector('.design-material').value.trim(),qty:Number(x.querySelector('.design-qty').value||0),unit:x.querySelector('.design-unit').value,stage:x.querySelector('.design-stage').value,progress:0,amount:Number(x.querySelector('.design-amount').value||0)})).filter(x=>x.id);if(!lines.length){toast('Add at least one Design ID','error');return}const existing=data.orders.find(o=>o.id===id);if(existing){existing.designs.push(...lines);existing.customer=customer;existing.poc=val('order-poc');existing.amount=Number(val('order-amount')||existing.amount)}else data.orders.push({id,customer,date:val('order-date'),delivery:val('order-delivery'),poc:val('order-poc'),priority:val('order-priority'),status:val('order-status'),amount:Number(val('order-amount')||0),designs:lines});persist();closeModal();render();toast(`${id} saved with ${lines.length} design(s)`,'success')}
function saveEditOrder(){const o=data.orders.find(x=>x.id===state.orderId);if(!o)return;Object.assign(o,{customer:val('edit-customer'),poc:val('edit-poc'),delivery:val('edit-delivery'),priority:val('edit-priority'),status:val('edit-status')});persist();closeModal();render();toast('Order updated','success')}
function savePayment(){const p={id:val('pay-id'),orderId:val('pay-order'),vendor:val('pay-vendor'),invoice:val('pay-invoice'),amount:Number(val('pay-amount')||0),date:val('pay-date'),method:val('pay-method'),reference:val('pay-reference'),status:val('pay-status')};if(!p.id||!p.orderId||!p.vendor||!p.amount){toast('Transaction ID, Order ID, Vendor and Amount are required','error');return}data.payments.push(p);persist();closeModal();render();toast('Payment entry saved','success')}
function savePurchase(){data.purchases.push({id:val('purchase-id'),orderIds:val('purchase-orders').split(',').map(x=>x.trim()).filter(Boolean),vendor:val('purchase-vendor'),materials:val('purchase-materials').split(',').map(x=>x.trim()).filter(Boolean),qty:val('purchase-qty'),rate:val('purchase-rate'),total:Number(val('purchase-total')||0),date:val('purchase-date'),invoice:val('purchase-invoice'),status:val('purchase-status')});persist();closeModal();render();toast('Purchase entry saved','success')}
function saveConsumption(){const d=val('cons-design');const row={designId:d,orderId:val('cons-order'),material:val('cons-material'),issued:Number(val('cons-issued')||0),consumed:Number(val('cons-consumed')||0),balance:Number(val('cons-balance')||0),wastage:Number(val('cons-wastage')||0),unit:val('cons-unit'),date:val('cons-date')};localStorage.setItem('aravliLastConsumption',JSON.stringify(row));persist();closeModal();render();toast(`Consumption saved for ${d}`,'success')}
function saveMaterial(){const m={id:val('material-id'),name:val('material-name'),type:val('material-type'),purchased:Number(val('material-purchased')||0),warehouse:Number(val('material-warehouse')||0),vendor:Number(val('material-vendor')||0),dyeing:Number(val('material-dyeing')||0),production:Number(val('material-production')||0),available:Number(val('material-available')||0),status:val('material-status')};if(!m.id||!m.name||!m.type){toast('Material ID, name and type are required','error');return}data.materials.push(m);persist();closeModal();render();toast('Material added','success')}
function saveReceive(){toast('Material receipt saved','success');closeModal();render()}
function saveIssue(){toast('Material issue saved','success');closeModal();render()}
function saveDyeing(){data.dyeing.push({id:val('dye-id'),orderId:val('dye-order'),designId:val('dye-design'),material:val('dye-material'),shade:val('dye-shade'),required:Number(val('dye-required')||0),issued:Number(val('dye-issued')||0),vendor:val('dye-vendor'),expected:val('dye-expected'),status:'Active Sample'});persist();closeModal();render();toast('Active sample saved','success')}
function saveDesign(){data.designs.push({id:val('design-id'),name:val('design-name'),size:val('design-size'),orderId:val('design-order'),materials:val('design-materials'),yarn:val('design-yarn'),materialCost:Number(val('design-material-cost')||0),weavingCost:Number(val('design-weaving-cost')||0),totalCost:Number(val('design-total-cost')||0),status:'Active Sample'});persist();closeModal();render();toast('Design saved','success')}
function saveTransport(){data.transport.push({id:val('trn-id'),orderId:val('trn-order'),eway:val('trn-eway'),vehicle:val('trn-vehicle'),vehicleNo:val('trn-vehicle-no'),driver:val('trn-driver'),from:val('trn-from'),to:val('trn-to'),qty:val('trn-qty'),status:val('trn-status')});persist();closeModal();render();toast('Transport entry saved','success')}
function saveWeaving(){const row={orderId:val('weave-order'),designs:val('weave-designs').split(',').map(x=>x.trim()).filter(Boolean),qty:val('weave-qty'),produced:val('weave-produced'),remaining:val('weave-remaining'),expected:val('weave-expected'),status:val('weave-status')};if(!row.orderId||!row.designs.length||!row.qty||!row.produced||!row.remaining){toast('Order ID, designs, quantity, produced and remaining are required','error');return}data.weaving.push(row);persist();closeModal();render();toast('Weaving entry saved','success')}
function saveVendorWizard(){captureVendorStep();const d=state.vendorDraft||{};if(!d.id||!d.name||!d.category||!d.contact||!d.services?.length){toast('Vendor ID, name, category, contact and at least one service are required','error');return}const v={id:d.id,name:d.name,category:d.category,contact:d.contact,services:d.services,status:d.status||'Pending Verification'};data.vendors.push(v);persist();state.vendorStep=1;state.vendorDraft={};closeModal();render();toast(`${v.id} onboarded`,'success')}

function openModal(type){state.modal=type;document.getElementById('modal-root').innerHTML=type==='inventorySection'?inventorySectionModal():type==='vendorPayments'?vendorPaymentsModal():type==='vendorService'?vendorServiceModal():type==='designExtra'?designExtraModal():modal(type)}
function closeModal(){state.modal=null;document.getElementById('modal-root').innerHTML=''}
function inventorySectionModal(){const type=state.inventorySection;let rows=[];if(type==='Vendor')rows=data.materials.map(m=>`<tr><td>${m.id}</td><td>${m.name}</td><td>${m.type}</td><td>${m.vendor} kg</td><td>${m.available} kg</td><td>${badge(m.status)}</td></tr>`);else rows=data.materials.map(m=>`<tr><td>${m.id}</td><td>${m.name}</td><td>${m.type}</td><td>${m[type.toLowerCase()]??m.warehouse} kg</td><td>${m.available} kg</td><td>${badge(m.status)}</td></tr>`);return `<div class="modal-backdrop"><div class="modal wide"><div class="modal-head"><h3>${esc(type)} Distribution Details</h3><button class="close" onclick="closeModal()">×</button></div><div class="modal-body"><p class="muted">Complete item-level details for the selected inventory section.</p>${tableCard(['Material ID','Material','Type','Section Qty','Available','Status'],rows)}</div></div></div>`}
function vendorPaymentsModal(){const vendor=state.modalData?.vendor||'';const rows=data.payments.filter(p=>p.vendor===vendor).map(p=>`<tr><td>${p.orderId}</td><td>${p.id}</td><td>${p.invoice}</td><td>${money(p.amount)}</td><td>${p.date}</td><td>${p.method}</td><td>${p.reference}</td><td>${badge(p.status)}</td></tr>`);return `<div class="modal-backdrop"><div class="modal wide"><div class="modal-head"><h3>${esc(vendor)} · Order-wise Payments</h3><button class="close" onclick="closeModal()">×</button></div><div class="modal-body"><div class="section-title"><h3>Complete payment details</h3><button class="btn primary" onclick="closeModal();openModal('payment')">+ Payment Entry</button></div>${tableCard(['Order ID','Transaction ID','Invoice','Amount','Payment Date','Method','Reference','Status'],rows)}</div></div></div>`}
function vendorServiceModal(){const vendor=state.modalData?.vendor||'';const service=state.modalData?.service||'';const rows=data.orders.filter(o=>o.designs.some(d=>d.stage.toLowerCase().includes(service.toLowerCase().slice(0,4))||service==='Dyeing')).map(o=>`<tr><td>${o.id}</td><td>${o.customer}</td><td>${o.designs.map(d=>d.id).join(', ')}</td><td>${service}</td><td>${badge(o.status)}</td></tr>`);return `<div class="modal-backdrop"><div class="modal wide"><div class="modal-head"><h3>${esc(vendor)} · ${esc(service)}</h3><button class="close" onclick="closeModal()">×</button></div><div class="modal-body">${tableCard(['Order ID','Customer','Design IDs','Service / Work','Order Status'],rows)}</div></div></div>`}
function toast(msg,type=''){const r=document.getElementById('toast-root'),el=document.createElement('div');el.className='toast '+type;el.textContent=msg;r.appendChild(el);setTimeout(()=>el.remove(),2800)}
function openOrder(id){state.page='orderDetail';state.orderId=id;state.orderTab='Overview';render()}
function navigate(p){state.page=p;state.sidebar=false;render()}
function filterTable(input){const table=input.closest('.table-card').querySelector('tbody');const q=input.value.toLowerCase();[...table.rows].forEach(r=>r.style.display=r.innerText.toLowerCase().includes(q)?'':'none')}
function openSearch(){state.searchOpen=true;render()}
function closeSearch(){state.searchOpen=false;render()}
function searchOverlay(){return `<div class="command"><div class="command-box"><input autofocus class="command-input" placeholder="Search Order ID, Vendor, Material, Design ID..." oninput="searchGlobal(this.value)"><div id="search-results" class="search-results">${searchResults('')}</div></div></div>`}
function searchResults(q){q=q.toLowerCase();const all=[];data.orders.forEach(o=>all.push(['Order',o.id,o.customer]));data.vendors.forEach(v=>all.push(['Vendor',v.id,v.name]));data.materials.forEach(m=>all.push(['Material',m.id,m.name]));data.designs.forEach(d=>all.push(['Design',d.id,d.name]));const f=all.filter(x=>`${x[0]} ${x[1]} ${x[2]}`.toLowerCase().includes(q));return f.map(x=>`<div class="result" onclick="selectSearch('${x[0]}','${x[1]}')"><div><strong>${esc(x[1])}</strong><small>${x[0]} · ${esc(x[2])}</small></div><span>→</span></div>`).join('')||'<div class="empty">No search results</div>'}
function searchGlobal(q){document.getElementById('search-results').innerHTML=searchResults(q)}
function selectSearch(type,id){closeSearch();if(type==='Order')openOrder(id);else if(type==='Vendor')openVendorPayments(data.vendors.find(v=>v.id===id)?.name||'');else if(type==='Material')openMaterialDetail(id);else {navigate('designs');}}
function shell(){return `<div class="app-shell"><aside class="sidebar ${state.sidebar?'open':''}"><div class="brand"><div class="brand-row"><img src="assets/aravli-logo.jpeg" class="brand-logo" alt="Aravli Crafts"><div><h2>ARAVLI CRAFTS</h2><p>OPERATIONS PLATFORM</p></div></div></div><nav class="nav"><div class="nav-label">MAIN</div>${['dashboard','orders','vendors','inventory','dyeing','designs','production','transport','finance'].map(p=>`<button class="${state.page===p?'active':''}" onclick="navigate('${p}')"><span class="ico">${icons[p]}</span>${labels[p]}</button>`).join('')}<div class="nav-label">MANAGEMENT</div>${['notifications','reports'].map(p=>`<button class="${state.page===p?'active':''}" onclick="navigate('${p}')"><span class="ico">${icons[p]}</span>${labels[p]}</button>`).join('')}</nav><div class="profile"><div class="profile-card"><div class="avatar">AC</div><div><strong>ANKAN</strong><small>Master Administrator · Full access</small></div><button class="icon-btn" style="margin-left:auto;width:30px;height:30px" onclick="state.login=true;render()">↪</button></div></div></aside><main class="main"><header class="topbar"><button class="menu-btn" onclick="state.sidebar=!state.sidebar;render()">☰</button><div class="global-search" onclick="openSearch()"><span>⌕</span><input placeholder="Search anything..." readonly><kbd>Ctrl K</kbd></div><div class="top-actions"><button class="icon-btn hide-mobile" onclick="openSearch()">⌕</button><button class="icon-btn" onclick="navigate('notifications')">♧<span class="notif-dot"></span></button><div class="avatar">AC</div></div></header><section class="content" id="content">${pageView()}</section></main><nav class="mobile-bottom">${['dashboard','orders','inventory','finance'].map(p=>`<button class="${state.page===p?'active':''}" onclick="navigate('${p}')"><span style="font-size:16px">${icons[p]}</span>${labels[p]}</button>`).join('')}<button onclick="state.sidebar=!state.sidebar;render()">☰<span>Menu</span></button></nav>${state.searchOpen?searchOverlay():''}</div>`}
const icons={dashboard:'⌂',orders:'▤',vendors:'♙',inventory:'▦',dyeing:'◈',designs:'◇',production:'⚙',transport:'➜',finance:'₹',notifications:'●',reports:'▥'};
const labels={dashboard:'Dashboard',orders:'Orders',vendors:'Vendors',inventory:'Inventory',dyeing:'Dyeing',designs:'Designs',production:'Weaving',transport:'Transport',finance:'Finance',notifications:'Notifications',reports:'Reports'};
function pageView(){if(state.page==='dashboard')return dashboard();if(state.page==='orders')return ordersPage();if(state.page==='orderDetail')return orderDetail(state.orderId);if(state.page==='vendors')return vendorsPage();if(state.page==='inventory')return inventoryPage();if(state.page==='finance')return financePage();return moduleGeneric(state.page)}
function loginView(){return `<div class="login"><section class="login-left"><img src="assets/aravli-logo.jpeg" class="login-logo" alt="Aravli Crafts"><div class="eyebrow" style="color:#c9d5e5">INTEGRATED OPERATIONS</div><h1>One Order.<br>Complete Journey.</h1><p>Aravli Crafts operations workspace connecting orders, designs, materials, vendors, dyeing, weaving, transport and finance through one traceable operating layer.</p><div class="login-pills">${['Order Traceability','Inventory Intelligence','Vendor Control','Financial Operations'].map(x=>`<span class="badge info">${x}</span>`).join('')}</div></section><section class="login-right"><div class="login-card"><img src="assets/aravli-logo.jpeg" class="login-card-logo" alt="Aravli Crafts"><div class="eyebrow">MASTER ACCESS</div><h2>Welcome back</h2><p>Sign in to your Aravli Crafts operations workspace.</p><div class="field"><label>Username</label><input id="login-user" value="ANKAN"></div><div class="field"><label>Password</label><input id="login-pass" type="password" value="ANKAN@123"></div><button class="btn primary" style="width:100%;padding:11px" onclick="login()">Sign In</button><div class="login-foot"><span>Prototype environment</span><span>Master Administrator</span></div></div></section></div>`}
function login(){const u=val('login-user'),p=val('login-pass');if(!u||!p){toast('Enter username and password','error');return}state.login=false;render();toast('Signed in successfully','success')}
function render(){document.getElementById('app').innerHTML=state.login?loginView():shell()}
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch()}if(e.key==='Escape')closeSearch()});
render();
